import{_ as t,o as s,c as n,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const g=JSON.parse('{"title":"第 18 章 如何进行多 Agent 系统设计","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 18 章 如何进行多 Agent 系统设计.md","filePath":"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 18 章 如何进行多 Agent 系统设计.md"}'),l={name:"bluebook/第三篇 进阶篇：把案例变成自己的工作系统/第 18 章 如何进行多 Agent 系统设计.md"};function p(i,a,o,d,r,h){return s(),n("div",null,[...a[0]||(a[0]=[e(`<div class="tip custom-block"><p class="custom-block-title">🎈 想读易懂版？</p><p>本章有<strong>易懂版</strong>（大白话讲重点，10 分钟读完）：[第 18 章 如何进行多 Agent 系统设计（易懂版）](../../easy/第18章 如何进行多 Agent 系统设计（易懂版）.md)</p></div><h1 id="第-18-章-如何进行多-agent-系统设计" tabindex="-1">第 18 章 如何进行多 Agent 系统设计 <a class="header-anchor" href="#第-18-章-如何进行多-agent-系统设计" aria-label="Permalink to &quot;第 18 章 如何进行多 Agent 系统设计&quot;">​</a></h1><blockquote><p>本章目标：掌握多 Agent 系统设计的方法论——第一原则、适用判断、五步设计法、黄金结构与常见错误。<strong>多 Agent 系统设计，本质是组织结构设计：拆得好，是团队；拆得差，是团伙。</strong></p></blockquote><h2 id="_18-1-从-一个-agent-到-一个系统" tabindex="-1">18.1 从&quot;一个 Agent&quot;到&quot;一个系统&quot; <a class="header-anchor" href="#_18-1-从-一个-agent-到-一个系统" aria-label="Permalink to &quot;18.1 从&quot;一个 Agent&quot;到&quot;一个系统&quot;&quot;">​</a></h2><p>第 8 章、第 16 章讲了怎么用团队。这一章讲<strong>设计</strong>：当你要解决一个复杂问题，怎么设计出一套多 Agent 协作的系统，而不是随手拉几个人。</p><h3 id="_18-1-1-设计-vs-使用" tabindex="-1">18.1.1 设计 vs 使用 <a class="header-anchor" href="#_18-1-1-设计-vs-使用" aria-label="Permalink to &quot;18.1.1 设计 vs 使用&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>使用（第 8、16 章）：现成的团队怎么用起来</span></span>
<span class="line"><span>设计（本章）：面对新问题，怎么设计出合适的协作结构</span></span></code></pre></div><p><strong>设计在前，使用在后</strong>——设计错了，怎么用都别扭。</p><h2 id="_18-2-设计的第一原则-能不拆就不拆" tabindex="-1">18.2 设计的第一原则：能不拆就不拆 <a class="header-anchor" href="#_18-2-设计的第一原则-能不拆就不拆" aria-label="Permalink to &quot;18.2 设计的第一原则：能不拆就不拆&quot;">​</a></h2><p>多 Agent 系统有成本：沟通开销、上下文割裂、结果不一致。所以：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>单 Agent 能解决的 → 绝不拆</span></span>
<span class="line"><span>任务可串行完成   → 不必并行</span></span>
<span class="line"><span>只有拆分收益 &gt; 协作成本 → 才拆</span></span></code></pre></div><p><strong>多 Agent 是手段，不是目的。</strong></p><h3 id="_18-2-1-拆分的成本清单" tabindex="-1">18.2.1 拆分的成本清单 <a class="header-anchor" href="#_18-2-1-拆分的成本清单" aria-label="Permalink to &quot;18.2.1 拆分的成本清单&quot;">​</a></h3><table tabindex="0"><thead><tr><th>成本</th><th>说明</th></tr></thead><tbody><tr><td>沟通开销</td><td>成员之间传递信息要花时间</td></tr><tr><td>上下文割裂</td><td>每个成员只看到部分信息，可能误判</td></tr><tr><td>结果不一致</td><td>不同成员产出风格/口径可能打架</td></tr><tr><td>管理开销</td><td>Leader 要协调、验收、处理阻塞</td></tr></tbody></table><h2 id="_18-3-什么样的任务值得多-agent" tabindex="-1">18.3 什么样的任务值得多 Agent <a class="header-anchor" href="#_18-3-什么样的任务值得多-agent" aria-label="Permalink to &quot;18.3 什么样的任务值得多 Agent&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>√ 多个专业角色（设计、开发、测试）</span></span>
<span class="line"><span>√ 可并行（各部分互不依赖）</span></span>
<span class="line"><span>√ 单个 Agent 上下文装不下</span></span>
<span class="line"><span>√ 需要交叉验证（写的人不能同时验）</span></span>
<span class="line"><span>× 需求未定、探索阶段</span></span>
<span class="line"><span>× 任务小到一句话能说清</span></span></code></pre></div><h3 id="_18-3-1-判断流程" tabindex="-1">18.3.1 判断流程 <a class="header-anchor" href="#_18-3-1-判断流程" aria-label="Permalink to &quot;18.3.1 判断流程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任务复杂吗？——否 → 单人</span></span>
<span class="line"><span>是 ↓</span></span>
<span class="line"><span>能拆成相对独立的子任务吗？——否 → 单人</span></span>
<span class="line"><span>是 ↓</span></span>
<span class="line"><span>拆分收益 &gt; 协作成本？——否 → 单人</span></span>
<span class="line"><span>是 ↓</span></span>
<span class="line"><span>✅ 设计多 Agent 系统</span></span></code></pre></div><h2 id="_18-4-设计一个多-agent-系统的五步法" tabindex="-1">18.4 设计一个多 Agent 系统的五步法 <a class="header-anchor" href="#_18-4-设计一个多-agent-系统的五步法" aria-label="Permalink to &quot;18.4 设计一个多 Agent 系统的五步法&quot;">​</a></h2><h3 id="第-1-步-定义目标与产出" tabindex="-1">第 1 步：定义目标与产出 <a class="header-anchor" href="#第-1-步-定义目标与产出" aria-label="Permalink to &quot;第 1 步：定义目标与产出&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>目标：上线一个新功能</span></span>
<span class="line"><span>产出：代码 + 测试 + 文档 + 上线检查单</span></span></code></pre></div><p><strong>先想清楚&quot;最后要什么&quot;，才谈怎么拆。</strong></p><h3 id="第-2-步-识别角色" tabindex="-1">第 2 步：识别角色 <a class="header-anchor" href="#第-2-步-识别角色" aria-label="Permalink to &quot;第 2 步：识别角色&quot;">​</a></h3><p>按任务自然边界切：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>规划（拆任务）→ 开发（写代码）→ 测试（验证）→ 文档（沉淀）→ 评审（把关）</span></span></code></pre></div><p><strong>角色数量控制在 3～5 个</strong>——角色过细，沟通成本爆炸。</p><h3 id="第-3-步-定义每个角色的输入输出" tabindex="-1">第 3 步：定义每个角色的输入输出 <a class="header-anchor" href="#第-3-步-定义每个角色的输入输出" aria-label="Permalink to &quot;第 3 步：定义每个角色的输入输出&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>开发：输入=需求文档；输出=代码 + 自测说明</span></span>
<span class="line"><span>测试：输入=代码 + 需求；输出=测试报告（通过/问题清单）</span></span></code></pre></div><p><strong>每个角色都要回答四个问题：</strong></p><ol><li>我的输入是什么？（谁给我什么）</li><li>我的输出是什么？（我交付什么）</li><li>我的验收标准是什么？（怎样算完成）</li><li>我依赖谁、谁依赖我？（协作关系）</li></ol><h3 id="第-4-步-设计协作关系" tabindex="-1">第 4 步：设计协作关系 <a class="header-anchor" href="#第-4-步-设计协作关系" aria-label="Permalink to &quot;第 4 步：设计协作关系&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>规划 → 开发 → 测试 → 评审</span></span>
<span class="line"><span>         ↘ 文档 ↙</span></span></code></pre></div><p>明确三件事：<strong>谁给谁交付、谁验证谁、谁有最终决定权。</strong></p><table tabindex="0"><thead><tr><th>关系</th><th>说明</th></tr></thead><tbody><tr><td>依赖</td><td>B 需要 A 的产出才能开工</td></tr><tr><td>验证</td><td>测试验证开发的产出</td></tr><tr><td>决策</td><td>Leader 对最终交付有决定权</td></tr></tbody></table><h3 id="第-5-步-设定检查点与回退" tabindex="-1">第 5 步：设定检查点与回退 <a class="header-anchor" href="#第-5-步-设定检查点与回退" aria-label="Permalink to &quot;第 5 步：设定检查点与回退&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>检查点：开发完成 → 测试验收 → 评审通过 → 交付</span></span>
<span class="line"><span>回退：测试发现问题 → 打回开发，附问题清单</span></span></code></pre></div><p><strong>检查点 = 质量闸门；回退路径 = 出错时的逃生通道。</strong> 两者缺一不可。</p><h2 id="_18-5-多-agent-系统的黄金结构" tabindex="-1">18.5 多 Agent 系统的黄金结构 <a class="header-anchor" href="#_18-5-多-agent-系统的黄金结构" aria-label="Permalink to &quot;18.5 多 Agent 系统的黄金结构&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>         Leader（我：拆解、协调、验收）</span></span>
<span class="line"><span>        /     |      \\      \\</span></span>
<span class="line"><span>   规划   开发    测试    文档</span></span>
<span class="line"><span>     \\      \\      /      /</span></span>
<span class="line"><span>        交叉验证 → 汇总交付</span></span></code></pre></div><p><strong>核心规则：写的人不验，验的人不写。</strong> 这是质量的第一道保险。</p><h3 id="_18-5-1-为什么-写的人不验" tabindex="-1">18.5.1 为什么&quot;写的人不验&quot; <a class="header-anchor" href="#_18-5-1-为什么-写的人不验" aria-label="Permalink to &quot;18.5.1 为什么&quot;写的人不验&quot;&quot;">​</a></h3><p>自己写的代码自己验，容易&quot;验出自己想要的答案&quot;（思维定式）。<strong>独立的验证者才能发现盲区</strong>——这是测试角色存在的根本原因。</p><h2 id="_18-6-常见设计错误" tabindex="-1">18.6 常见设计错误 <a class="header-anchor" href="#_18-6-常见设计错误" aria-label="Permalink to &quot;18.6 常见设计错误&quot;">​</a></h2><table tabindex="0"><thead><tr><th>错误</th><th>后果</th><th>修正</th></tr></thead><tbody><tr><td>角色过细</td><td>沟通成本爆炸</td><td>合并到 3～5 个角色</td></tr><tr><td>没有 Leader 验收</td><td>各做各的，没人对整体负责</td><td>明确唯一负责人</td></tr><tr><td>任务边界重叠</td><td>重复劳动</td><td>每个子任务唯一归属</td></tr><tr><td>全程并行</td><td>依赖没处理好</td><td>先画依赖图再排期</td></tr><tr><td>没有回退路径</td><td>出错就卡死</td><td>预设打回机制</td></tr></tbody></table><h3 id="_18-6-1-依赖图先行" tabindex="-1">18.6.1 依赖图先行 <a class="header-anchor" href="#_18-6-1-依赖图先行" aria-label="Permalink to &quot;18.6.1 依赖图先行&quot;">​</a></h3><p><strong>设计阶段先画依赖图，再排执行计划：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>规划 ──→ 开发A ──→ 测试 ──→ 评审</span></span>
<span class="line"><span>  │      开发B ──↗</span></span>
<span class="line"><span>  └──→ 文档（可与开发并行）</span></span></code></pre></div><ul><li>有依赖的：串行，先做上游；</li><li>无依赖的：并行，同时开工；</li><li><strong>并行不是目的，按依赖正确排序才是。</strong></li></ul><h2 id="_18-7-多-agent-设计的进阶原则" tabindex="-1">18.7 多 Agent 设计的进阶原则 <a class="header-anchor" href="#_18-7-多-agent-设计的进阶原则" aria-label="Permalink to &quot;18.7 多 Agent 设计的进阶原则&quot;">​</a></h2><h3 id="_18-7-1-从-静态结构-到-动态调整" tabindex="-1">18.7.1 从&quot;静态结构&quot;到&quot;动态调整&quot; <a class="header-anchor" href="#_18-7-1-从-静态结构-到-动态调整" aria-label="Permalink to &quot;18.7.1 从&quot;静态结构&quot;到&quot;动态调整&quot;&quot;">​</a></h3><p>好的设计不是一次定死的，而是<strong>根据执行反馈动态调整</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>发现开发任务太大 → 再拆成 2 个子任务</span></span>
<span class="line"><span>发现测试无事可做 → 调整测试介入时机</span></span>
<span class="line"><span>发现需求变化 → 重新评估拆分是否还合理</span></span></code></pre></div><h3 id="_18-7-2-设计文档的价值" tabindex="-1">18.7.2 设计文档的价值 <a class="header-anchor" href="#_18-7-2-设计文档的价值" aria-label="Permalink to &quot;18.7.2 设计文档的价值&quot;">​</a></h3><p><strong>多 Agent 系统的设计，本身就应该写成文档</strong>（角色表、依赖图、检查点）——它既是执行蓝图，也是复盘依据，还能沉淀为团队模板。</p><h2 id="_18-8-练习" tabindex="-1">18.8 练习 <a class="header-anchor" href="#_18-8-练习" aria-label="Permalink to &quot;18.8 练习&quot;">​</a></h2><ol><li>选一个你熟悉的复杂任务，按五步法画出系统设计；</li><li>画出角色关系图，标出依赖和检查点；</li><li>用真实任务跑一轮，复盘：拆分是否合理？哪里协作成本最高？</li><li>把这份设计写成文档（角色表 + 依赖图 + 检查点），沉淀为模板。</li></ol><hr><blockquote><p>小结：多 Agent 系统设计，本质是<strong>组织结构设计</strong>。拆得好，是团队；拆得差，是团伙。<strong>能不拆就不拆 + 写的人不验 + 检查点与回退齐全</strong>，就是设计心法。下一章：自动化工作流的可靠性。</p></blockquote>`,58)])])}const u=t(l,[["render",p]]);export{g as __pageData,u as default};
